-- Seed kuliner: 3 makanan khas × 38 provinsi
-- category slug: kuliner
-- Generated by scripts/seed-kuliner.mjs

BEGIN;

DELETE FROM cultures WHERE category_id = (SELECT id FROM categories WHERE slug = 'kuliner');

INSERT INTO cultures (province_id, category_id, name, content, media_url, location, maps_url, slug)
SELECT p.id, c.id, v.name, v.content, v.media_url, v.location, v.maps_url, v.slug
FROM (SELECT id FROM categories WHERE slug = 'kuliner') c
CROSS JOIN (VALUES
  ('aceh', 'Mie Aceh', '<p>Mie Aceh adalah mie kuning tebal berbumbu rempah khas Aceh yang biasanya disajikan goreng atau kuah. Cita rasanya pedas, gurih, dan aromatik berkat penggunaan jinten, kapulaga, serta cabai.</p><p>Hidangan ini sering dilengkapi daging sapi, kambing, atau seafood seperti udang dan cumi. Mie Aceh menjadi ikon kuliner yang mudah dijumpai di warung hingga restoran di seluruh Aceh.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Mie_Aceh.jpg/1280px-Mie_Aceh.jpg', 'Banda Aceh', 'https://www.google.com/maps/search/?api=1&query=Mie%20Aceh%20Aceh', 'mie-aceh'),
  ('aceh', 'Kuah Beulangong', '<p>Kuah Beulangong adalah gulai daging kambing dengan kuah santan kental yang biasa disajikan pada acara adat dan kenduri di Aceh.</p><p>Rempah-rempah lokal memberikan aroma kuat, sementara tekstur daging yang empuk membuat hidangan ini istimewa di meja perayaan.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Aceh Besar', 'https://www.google.com/maps/search/?api=1&query=Kuah%20Beulangong%20Aceh', 'kuah-beulangong'),
  ('aceh', 'Timphan', '<p>Timphan adalah kue tradisional Aceh berbahan tepung ketan dan pisang yang dibungkus daun pisang lalu dikukus.</p><p>Teksturnya kenyal lembut dengan rasa manis natural dari pisang. Timphan sering muncul saat Lebaran dan upacara adat sebagai sajian penutup.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Banda Aceh', 'https://www.google.com/maps/search/?api=1&query=Timphan%20Aceh', 'timphan'),
  ('sumatera-utara', 'Bika Ambon', '<p>Bika Ambon adalah kue bersarang khas Medan dengan tekstur kenyal berongga dan aroma daun pandan atau kayu manis.</p><p>Meski namanya memuat kata Ambon, kue ini justru menjadi oleh-oleh wajib dari Sumatera Utara dan tersedia dalam berbagai rasa modern.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Medan', 'https://www.google.com/maps/search/?api=1&query=Bika%20Ambon%20Sumatera%20Utara', 'bika-ambon'),
  ('sumatera-utara', 'Soto Medan', '<p>Soto Medan memadukan kuah santan gurih dengan irisan daging, bihun, dan kentang goreng. Aromanya kaya karena rempah Melayu-Batak.</p><p>Hidangan ini populer sebagai sarapan maupun makan siang, sering dilengkapi kerupuk dan sambal untuk sentuhan pedas.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Soto_ayam.JPG/1280px-Soto_ayam.JPG', 'Medan', 'https://www.google.com/maps/search/?api=1&query=Soto%20Medan%20Sumatera%20Utara', 'soto-medan'),
  ('sumatera-utara', 'Arsik Ikan Mas', '<p>Arsik adalah masakan Batak Toba berupa ikan mas yang dimasak dengan andaliman, kecombrang, dan rempah kuning.</p><p>Cita rasa unik andaliman memberi sensasi getar di lidah. Arsik sering disajikan pada acara adat Batak sebagai hidangan kehormatan.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Toba', 'https://www.google.com/maps/search/?api=1&query=Arsik%20Ikan%20Mas%20Sumatera%20Utara', 'arsik-ikan-mas'),
  ('sumatera-barat', 'Rendang', '<p>Rendang adalah daging sapi yang dimasak lama dalam santan dan rempah hingga kuah mengering dan bumbu meresap sempurna.</p><p>Diakui dunia sebagai salah satu makanan terenak, rendang menjadi kebanggaan Minangkabau dan ikon kuliner Indonesia.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Rendang_daging_sapi_asli_Padang.JPG/1280px-Rendang_daging_sapi_asli_Padang.JPG', 'Padang', 'https://www.google.com/maps/search/?api=1&query=Rendang%20Sumatera%20Barat', 'rendang'),
  ('sumatera-barat', 'Sate Padang', '<p>Sate Padang menyajikan tusuk daging dengan kuah kental berbumbu kunyit yang khas, berbeda dari sate kacang di Jawa.</p><p>Ada variasi Padang dan Pariaman dengan kekentalan kuah berbeda. Biasanya disantap dengan ketupat atau lontong.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Sate_ayam.jpg/1280px-Sate_ayam.jpg', 'Padang', 'https://www.google.com/maps/search/?api=1&query=Sate%20Padang%20Sumatera%20Barat', 'sate-padang'),
  ('sumatera-barat', 'Gulai Tunjang', '<p>Gulai Tunjang adalah gulai kikil sapi dalam kuah santan kuning berempah khas Minang.</p><p>Tekstur kenyal kikil berpadu kuah gurih pedas menjadikannya lauk favorit dalam sajian nasi Padang.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Nasi_Padang.jpg/1280px-Nasi_Padang.jpg', 'Padang', 'https://www.google.com/maps/search/?api=1&query=Gulai%20Tunjang%20Sumatera%20Barat', 'gulai-tunjang'),
  ('riau', 'Gulai Ikan Patin', '<p>Gulai ikan patin Riau dimasak dengan santan dan rempah lembut sehingga daging patin tetap lembut dan tidak amis.</p><p>Hidangan sungai ini mencerminkan kekayaan perairan Riau dan sering menjadi menu utama di rumah makan Melayu.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Pekanbaru', 'https://www.google.com/maps/search/?api=1&query=Gulai%20Ikan%20Patin%20Riau', 'gulai-ikan-patin-riau'),
  ('riau', 'Asam Pedas Ikan', '<p>Asam pedas Riau mengolah ikan dengan kuah asam dari belimbing wuluh atau asam kandis serta cabai.</p><p>Rasanya segar, pedas, dan sedikit asam — cocok dengan nasi hangat di iklim tropis pesisir.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Pekanbaru', 'https://www.google.com/maps/search/?api=1&query=Asam%20Pedas%20Ikan%20Riau', 'asam-pedas-ikan-riau'),
  ('riau', 'Bolu Kemojo', '<p>Bolu Kemojo adalah kue tradisional Melayu Riau berbentuk bunga kemojo dengan aroma pandan.</p><p>Teksturnya lembut dan manis sedang, sering dibawa sebagai oleh-oleh khas Pekanbaru.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Pekanbaru', 'https://www.google.com/maps/search/?api=1&query=Bolu%20Kemojo%20Riau', 'bolu-kemojo'),
  ('jambi', 'Tempoyak Ikan', '<p>Tempoyak adalah durian fermentasi yang diolah bersama ikan menjadi masakan beraroma kuat khas Jambi.</p><p>Perpaduan asam-manis fermentasi dengan ikan sungai menciptakan cita rasa yang berani dan sangat lokal.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Jambi', 'https://www.google.com/maps/search/?api=1&query=Tempoyak%20Ikan%20Jambi', 'tempoyak-ikan-jambi'),
  ('jambi', 'Gulai Tepek Ikan', '<p>Gulai Tepek Ikan memakai olahan daging ikan yang digiling dan dibentuk pipih, lalu dimasak dalam kuah gulai.</p><p>Hidangan ini umum di jamuan adat Jambi dan menunjukkan kreativitas pengolahan hasil sungai.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Jambi', 'https://www.google.com/maps/search/?api=1&query=Gulai%20Tepek%20Ikan%20Jambi', 'gulai-tepek-ikan'),
  ('jambi', 'Kerutup Ikan', '<p>Kerutup Ikan adalah ikan yang dibungkus daun dan rempah lalu dipanggang hingga harum.</p><p>Cara memasaknya menjaga kelembapan daging sekaligus menanamkan aroma daun dan bumbu ke dalam ikan.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Jambi', 'https://www.google.com/maps/search/?api=1&query=Kerutup%20Ikan%20Jambi', 'kerutup-ikan'),
  ('sumatera-selatan', 'Pempek', '<p>Pempek adalah olahan ikan giling dan sagu yang digoreng, disajikan dengan cuko pedas-manis khas Palembang.</p><p>Variannya banyak: kapal selam, lenjer, adaan, hingga keriting. Pempek sudah menjadi identitas kuliner Sumatera Selatan.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Pempek_candy.jpg/1280px-Pempek_candy.jpg', 'Palembang', 'https://www.google.com/maps/search/?api=1&query=Pempek%20Sumatera%20Selatan', 'pempek'),
  ('sumatera-selatan', 'Tekwan', '<p>Tekwan adalah sup bakso ikan dengan kuah bening gurih, ditambah bihun, jamur, dan bawang goreng.</p><p>Lebih ringan dari pempek goreng, tekwan cocok sebagai hidangan hangat sepanjang hari.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Palembang', 'https://www.google.com/maps/search/?api=1&query=Tekwan%20Sumatera%20Selatan', 'tekwan'),
  ('sumatera-selatan', 'Pindang Patin', '<p>Pindang Patin dimasak dengan kuah asam pedas yang kaya rempah, sering memakai nanas untuk kesegaran.</p><p>Daging patin yang berlemak berpadu kuah segar menjadikannya lauk favorit keluarga Palembang.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Palembang', 'https://www.google.com/maps/search/?api=1&query=Pindang%20Patin%20Sumatera%20Selatan', 'pindang-patin'),
  ('bengkulu', 'Pendap', '<p>Pendap adalah ikan yang dibumbui santan dan rempah, dibungkus daun talas, lalu dimasak lama hingga bumbu meresap.</p><p>Aroma daun talas memberi karakter unik. Pendap menjadi kebanggaan kuliner Bengkulu di acara adat maupun sehari-hari.</p>', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=1200&q=80', 'Bengkulu', 'https://www.google.com/maps/search/?api=1&query=Pendap%20Bengkulu', 'pendap'),
  ('bengkulu', 'Bainik', '<p>Bainik adalah ikan yang dibumbui pedas lalu dipanggang atau digoreng hingga kering gurih.</p><p>Sajian sederhana ini menonjolkan hasil laut Bengkulu dengan sentuhan cabai dan rempah lokal.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Bengkulu', 'https://www.google.com/maps/search/?api=1&query=Bainik%20Bengkulu', 'bainik'),
  ('bengkulu', 'Gulai Kembung', '<p>Gulai ikan kembung Bengkulu memakai santan dan bumbu kuning yang harum.</p><p>Ikan kembung yang ekonomis diolah menjadi lauk istimewa dengan kuah gurih pedas khas pesisir.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Bengkulu', 'https://www.google.com/maps/search/?api=1&query=Gulai%20Kembung%20Bengkulu', 'gulai-kembung-bengkulu'),
  ('lampung', 'Seruit', '<p>Seruit adalah ikan bakar atau goreng yang disantap dengan sambal terasi tempoyak khas Lampung.</p><p>Tradisi makan bersama seruit mencerminkan budaya kebersamaan masyarakat Lampung.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Bandar Lampung', 'https://www.google.com/maps/search/?api=1&query=Seruit%20Lampung', 'seruit'),
  ('lampung', 'Tempoyak Lampung', '<p>Tempoyak Lampung mengolah durian fermentasi menjadi sambal atau lauk yang asam-manis pedas.</p><p>Biasanya dipadukan dengan ikan. Aromanya kuat dan menjadi pembeda kuliner Lampung dari daerah lain.</p>', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=80', 'Lampung', 'https://www.google.com/maps/search/?api=1&query=Tempoyak%20Lampung%20Lampung', 'tempoyak-lampung'),
  ('lampung', 'Gulai Taboh', '<p>Gulai Taboh adalah gulai campuran sayur dan ikan dalam kuah santan berempah.</p><p>Hidangan rumahan ini kaya gizi dan sering muncul di meja makan keluarga Lampung.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Lampung', 'https://www.google.com/maps/search/?api=1&query=Gulai%20Taboh%20Lampung', 'gulai-taboh'),
  ('kepulauan-bangka-belitung', 'Mie Bangka', '<p>Mie Bangka adalah mie kuning yang disajikan dengan kuah atau digoreng, sering dilengkapi bakso ikan.</p><p>Pengaruh kuliner Tionghoa-Melayu terasa kuat. Mie Bangka menjadi menu andalan kota-kota di kepulauan ini.</p>', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=1200&q=80', 'Pangkalpinang', 'https://www.google.com/maps/search/?api=1&query=Mie%20Bangka%20Kepulauan%20Bangka%20Belitung', 'mie-bangka'),
  ('kepulauan-bangka-belitung', 'Lempah Kuning', '<p>Lempah Kuning adalah kuah ikan berbumbu kunyit, nanas, dan cabai yang segar pedas asam.</p><p>Hidangan laut ini sangat identik dengan Bangka Belitung dan cocok disantap dengan nasi putih.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Pangkalpinang', 'https://www.google.com/maps/search/?api=1&query=Lempah%20Kuning%20Kepulauan%20Bangka%20Belitung', 'lempah-kuning'),
  ('kepulauan-bangka-belitung', 'Otak-otak Bangka', '<p>Otak-otak Bangka terbuat dari ikan giling berbumbu yang dibungkus daun pisang lalu dibakar.</p><p>Disajikan dengan saus asam manis pedas. Teksturnya kenyal dan aroma bakaran daun pisang sangat menggoda.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Bangka', 'https://www.google.com/maps/search/?api=1&query=Otak-otak%20Bangka%20Kepulauan%20Bangka%20Belitung', 'otak-otak-bangka'),
  ('kepulauan-riau', 'Gonggong', '<p>Gonggong adalah siput laut khas Kepulauan Riau yang direbus dan disantap dengan saus sambal pedas.</p><p>Menarik dagingnya dari cangkang jadi bagian dari pengalaman makan. Gonggong ikon wisata kuliner Tanjung Pinang.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Tanjung Pinang', 'https://www.google.com/maps/search/?api=1&query=Gonggong%20Kepulauan%20Riau', 'gonggong'),
  ('kepulauan-riau', 'Laksa Kepri', '<p>Laksa Kepri adalah mie kuah santan berempah dengan pengaruh Melayu-Singapura-Malaysia.</p><p>Kuahnya kaya, sedikit pedas, dan biasanya dilengkapi tauge serta daun kesum.</p>', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?w=1200&q=80', 'Tanjung Pinang', 'https://www.google.com/maps/search/?api=1&query=Laksa%20Kepri%20Kepulauan%20Riau', 'laksa-kepri'),
  ('kepulauan-riau', 'Otak-otak Kepri', '<p>Otak-otak di Kepri digoreng atau dibakar dengan bumbu yang cenderung lebih pedas gurih.</p><p>Sering dijual di pinggir pantai dan pusat kuliner Batam sebagai camilan laut favorit.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Batam', 'https://www.google.com/maps/search/?api=1&query=Otak-otak%20Kepri%20Kepulauan%20Riau', 'otak-otak-kepri'),
  ('dki-jakarta', 'Kerak Telor', '<p>Kerak Telor adalah makanan Betawi dari beras ketan, telur, ebi, dan bawang goreng yang dimasak di atas wajan arang.</p><p>Tekstur luarnya garing, dalamnya pulen. Kerak Telor wajib ada di festival budaya Betawi.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Kerak_telor.jpg/1280px-Kerak_telor.jpg', 'Jakarta', 'https://www.google.com/maps/search/?api=1&query=Kerak%20Telor%20DKI%20Jakarta', 'kerak-telor'),
  ('dki-jakarta', 'Soto Betawi', '<p>Soto Betawi memakai kuah santan atau susu dengan daging sapi, jeroan, dan kentang goreng.</p><p>Gurihnya khas urban Betawi. Biasanya disajikan dengan emping dan jeruk nipis.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Soto_ayam.JPG/1280px-Soto_ayam.JPG', 'Jakarta', 'https://www.google.com/maps/search/?api=1&query=Soto%20Betawi%20DKI%20Jakarta', 'soto-betawi'),
  ('dki-jakarta', 'Gado-gado', '<p>Gado-gado adalah salad sayur Indonesia dengan saus kacang kental, tahu, tempe, dan kerupuk.</p><p>Versi Betawi sangat populer di Jakarta sebagai makanan sehat yang tetap mengenyangkan.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Gado_gado.jpg/1280px-Gado_gado.jpg', 'Jakarta', 'https://www.google.com/maps/search/?api=1&query=Gado-gado%20DKI%20Jakarta', 'gado-gado'),
  ('jawa-barat', 'Batagor', '<p>Batagor (bakso tahu goreng) adalah camilan Bandung dari tahu dan ikan digoreng, disiram saus kacang.</p><p>Ada juga versi kuah. Batagor menjadi oleh-oleh dan jajanan kaki lima paling dikenal di Jawa Barat.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Batagor_Bandung.jpg/1280px-Batagor_Bandung.jpg', 'Bandung', 'https://www.google.com/maps/search/?api=1&query=Batagor%20Jawa%20Barat', 'batagor'),
  ('jawa-barat', 'Surabi', '<p>Surabi adalah pancake tradisional beras dengan topping oncom, keju, atau kinca manis.</p><p>Dimasak di atas tungku tanah liat, aroma barunya sangat khas. Surabi malam hari di Bandung sudah jadi tradisi.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Bandung', 'https://www.google.com/maps/search/?api=1&query=Surabi%20Jawa%20Barat', 'surabi'),
  ('jawa-barat', 'Nasi Timbel', '<p>Nasi Timbel menyajikan nasi dibungkus daun pisang bersama lauk ayam, tahu, tempe, dan sambal.</p><p>Aroma daun pisang meresap ke nasi. Paket lengkap ini ikon kuliner Sunda sehari-hari.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Bogor', 'https://www.google.com/maps/search/?api=1&query=Nasi%20Timbel%20Jawa%20Barat', 'nasi-timbel'),
  ('jawa-tengah', 'Lumpia Semarang', '<p>Lumpia Semarang berisi rebung, telur, dan udang/daging dalam kulit tipis, disajikan basah atau goreng.</p><p>Pengaruh Tionghoa-Jawa sangat terasa. Lumpia jadi oleh-oleh wajib dari Kota Semarang.</p>', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=1200&q=80', 'Semarang', 'https://www.google.com/maps/search/?api=1&query=Lumpia%20Semarang%20Jawa%20Tengah', 'lumpia-semarang'),
  ('jawa-tengah', 'Soto Kudus', '<p>Soto Kudus berkuah bening dengan daging kerbau atau ayam, disajikan dalam mangkuk kecil.</p><p>Rasanya ringan namun kaya rempah. Tradisi porsi kecil membuat orang bisa mencicipi berkali-kali.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Soto_ayam.JPG/1280px-Soto_ayam.JPG', 'Kudus', 'https://www.google.com/maps/search/?api=1&query=Soto%20Kudus%20Jawa%20Tengah', 'soto-kudus'),
  ('jawa-tengah', 'Nasi Liwet Solo', '<p>Nasi Liwet Solo dimasak dengan santan dan disajikan bersama labu siam, ayam suwir, dan areh.</p><p>Citanya gurih lembut. Sering dimakan bersama di atas daun pisang sebagai simbol kebersamaan.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Surakarta', 'https://www.google.com/maps/search/?api=1&query=Nasi%20Liwet%20Solo%20Jawa%20Tengah', 'nasi-liwet-solo'),
  ('di-yogyakarta', 'Gudeg', '<p>Gudeg mengolah nangka muda dimasak santan dan gula aren hingga manis gurih, khas Yogyakarta.</p><p>Disajikan dengan krecek, ayam, dan telur. Gudeg adalah wajah kuliner keraton yang merakyat.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Gudeg_Yogyakarta.jpg/1280px-Gudeg_Yogyakarta.jpg', 'Yogyakarta', 'https://www.google.com/maps/search/?api=1&query=Gudeg%20DI%20Yogyakarta', 'gudeg'),
  ('di-yogyakarta', 'Bakpia Pathok', '<p>Bakpia Pathok adalah kue isi kacang hijau (dan varian modern lain) yang menjadi oleh-oleh legendaris Yogya.</p><p>Kulitnya renyah lembut. Nama Pathok merujuk kawasan produksi tradisionalnya.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Yogyakarta', 'https://www.google.com/maps/search/?api=1&query=Bakpia%20Pathok%20DI%20Yogyakarta', 'bakpia-pathok'),
  ('di-yogyakarta', 'Sate Klatak', '<p>Sate Klatak memakai tusuk besi bekas pelepah (klatak) dan daging kambing berbumbu sederhana.</p><p>Dipanggang hingga harum, disiram kuah gulai. Khas Bantul dan sangat populer di malam hari.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Sate_ayam.jpg/1280px-Sate_ayam.jpg', 'Bantul', 'https://www.google.com/maps/search/?api=1&query=Sate%20Klatak%20DI%20Yogyakarta', 'sate-klatak'),
  ('jawa-timur', 'Rawon', '<p>Rawon adalah sup daging berkuah hitam dari kluwek, khas Jawa Timur.</p><p>Rasanya gurih sedap dengan aroma khas. Biasanya disajikan dengan tauge pendek, telur asin, dan sambal.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Rawon_setan.jpg/1280px-Rawon_setan.jpg', 'Surabaya', 'https://www.google.com/maps/search/?api=1&query=Rawon%20Jawa%20Timur', 'rawon'),
  ('jawa-timur', 'Rujak Cingur', '<p>Rujak Cingur memadukan sayur, buah, tahu, tempe, dan cingur (moncong sapi) dengan saus petis.</p><p>Rasanya kompleks: manis, pedas, gurih, dan sedikit asin. Ikon kuliner Surabaya yang unik.</p>', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=1200&q=80', 'Surabaya', 'https://www.google.com/maps/search/?api=1&query=Rujak%20Cingur%20Jawa%20Timur', 'rujak-cingur'),
  ('jawa-timur', 'Lontong Balap', '<p>Lontong Balap berisi lontong, tauge, tahu goreng, dan lentho dengan kuah manis gurih.</p><p>Namanya merujuk pedagang yang dulu berjualan dengan berlari. Camilan khas Surabaya yang mengenyangkan.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Surabaya', 'https://www.google.com/maps/search/?api=1&query=Lontong%20Balap%20Jawa%20Timur', 'lontong-balap'),
  ('banten', 'Sate Bandeng', '<p>Sate Bandeng mengolah ikan bandeng tanpa duri yang dibumbui lalu dibakar utuh.</p><p>Teksturnya lembut dan gurih. Menjadi kebanggaan kuliner Banten, terutama Serang.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Serang', 'https://www.google.com/maps/search/?api=1&query=Sate%20Bandeng%20Banten', 'sate-bandeng'),
  ('banten', 'Rabeg', '<p>Rabeg adalah gulai daging kambing berbumbu kuat dengan kuah kental khas Banten.</p><p>Sering disajikan pada perayaan. Aroma rempahnya mengingatkan pada pengaruh kuliner pesisir dan Arab.</p>', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=1200&q=80', 'Serang', 'https://www.google.com/maps/search/?api=1&query=Rabeg%20Banten', 'rabeg'),
  ('banten', 'Angeun Lada', '<p>Angeun Lada adalah gulai daging berempah dengan cita rasa lada yang menonjol.</p><p>Pedas hangatnya cocok untuk iklim pegunungan Banten Selatan.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Pandeglang', 'https://www.google.com/maps/search/?api=1&query=Angeun%20Lada%20Banten', 'angeun-lada'),
  ('bali', 'Babi Guling', '<p>Babi Guling adalah babi utuh yang dipanggang berputar dengan bumbu base genep khas Bali.</p><p>Kulitnya garing, dagingnya berempah. Hidangan ini ikon upacara dan wisata kuliner Bali.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Babi_guling.jpg/1280px-Babi_guling.jpg', 'Gianyar', 'https://www.google.com/maps/search/?api=1&query=Babi%20Guling%20Bali', 'babi-guling'),
  ('bali', 'Ayam Betutu', '<p>Ayam Betutu dimasak lama dengan bumbu bali pedas dalam balutan daun pisang hingga empuk.</p><p>Versi Gilimanuk dan Gianyar sama-sama terkenal. Cocok disantap dengan nasi dan sambal matah.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Gilimanuk', 'https://www.google.com/maps/search/?api=1&query=Ayam%20Betutu%20Bali', 'ayam-betutu'),
  ('bali', 'Lawar', '<p>Lawar adalah campuran sayur, daging cincang, kelapa, dan bumbu Bali yang disajikan dalam upacara adat.</p><p>Ada lawar merah dan putih. Rasanya kompleks dan sangat mewakili dapur tradisional Bali.</p>', 'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?w=1200&q=80', 'Denpasar', 'https://www.google.com/maps/search/?api=1&query=Lawar%20Bali', 'lawar'),
  ('nusa-tenggara-barat', 'Ayam Taliwang', '<p>Ayam Taliwang adalah ayam bakar/goreng berbumbu cabai khas Lombok yang pedas membara.</p><p>Biasanya disantap dengan plecing kangkung. Menjadi ikon kuliner Nusa Tenggara Barat.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Ayam_Taliwang.jpg/1280px-Ayam_Taliwang.jpg', 'Mataram', 'https://www.google.com/maps/search/?api=1&query=Ayam%20Taliwang%20Nusa%20Tenggara%20Barat', 'ayam-taliwang'),
  ('nusa-tenggara-barat', 'Plecing Kangkung', '<p>Plecing Kangkung menyajikan kangkung rebus dengan sambal tomat-cabai yang segar pedas.</p><p>Pelengkap sempurna untuk ayam taliwang dan sate bulayak.</p>', 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?w=1200&q=80', 'Lombok', 'https://www.google.com/maps/search/?api=1&query=Plecing%20Kangkung%20Nusa%20Tenggara%20Barat', 'plecing-kangkung'),
  ('nusa-tenggara-barat', 'Sate Bulayak', '<p>Sate Bulayak adalah sate digulung dengan lembaran ketupat (bulayak) dan disiram bumbu kacang pedas.</p><p>Penyajiannya unik dan sangat fotogenik. Khas Lombok Tengah.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Sate_ayam.jpg/1280px-Sate_ayam.jpg', 'Lombok', 'https://www.google.com/maps/search/?api=1&query=Sate%20Bulayak%20Nusa%20Tenggara%20Barat', 'sate-bulayak'),
  ('nusa-tenggara-timur', 'Se''i Sapi', '<p>Se''i adalah daging asap khas NTT yang diasapkan dengan kayu lokal hingga harum dan empuk.</p><p>Disajikan dengan sambal lu''at. Se''i sapi maupun babi menjadi oleh-oleh populer dari Kupang.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Se%27i_sapi.jpg/1280px-Se%27i_sapi.jpg', 'Kupang', 'https://www.google.com/maps/search/?api=1&query=Se''i%20Sapi%20Nusa%20Tenggara%20Timur', 'sei-sapi'),
  ('nusa-tenggara-timur', 'Jagung Bose', '<p>Jagung Bose adalah jagung pipil yang dimasak dengan kacang dan santan hingga pulen gurih.</p><p>Makanan pokok tradisional Timor yang mengenyangkan dan kaya serat.</p>', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1200&q=80', 'Kupang', 'https://www.google.com/maps/search/?api=1&query=Jagung%20Bose%20Nusa%20Tenggara%20Timur', 'jagung-bose'),
  ('nusa-tenggara-timur', 'Kolo', '<p>Kolo adalah nasi atau jagung yang dimasak dalam bambu hingga aroma asap meresap.</p><p>Teknik memasak ini umum di NTT dan menghasilkan rasa yang sangat natural.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'NTT', 'https://www.google.com/maps/search/?api=1&query=Kolo%20Nusa%20Tenggara%20Timur', 'kolo-ntt'),
  ('kalimantan-barat', 'Bubur Pedas Pontianak', '<p>Bubur Pedas adalah bubur beras dengan aneka sayur dan rempah Melayu Pontianak yang harum pedas.</p><p>Bukan pedas membakar, melainkan kaya bumbu. Sering disajikan saat Ramadan dan acara adat.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Pontianak', 'https://www.google.com/maps/search/?api=1&query=Bubur%20Pedas%20Pontianak%20Kalimantan%20Barat', 'bubur-pedas-pontianak'),
  ('kalimantan-barat', 'Chai Kue', '<p>Chai Kue adalah kue kukus berisi sayur dengan kulit transparan khas Tionghoa Pontianak.</p><p>Disajikan dengan cabai cuka. Camilan favorit warga Pontianak sepanjang hari.</p>', 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=1200&q=80', 'Pontianak', 'https://www.google.com/maps/search/?api=1&query=Chai%20Kue%20Kalimantan%20Barat', 'chai-kue'),
  ('kalimantan-barat', 'Pengkang', '<p>Pengkang adalah ketan isi ebi yang dibungkus daun pisang lalu dibakar.</p><p>Aroma bakaran daun pisang berpadu gurih ebi. Jajanan tradisional Melayu Kalbar.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Pontianak', 'https://www.google.com/maps/search/?api=1&query=Pengkang%20Kalimantan%20Barat', 'pengkang'),
  ('kalimantan-tengah', 'Juhu Singkah', '<p>Juhu Singkah mengolah umbut rotan muda menjadi sayur berkuah khas Dayak Kalimantan Tengah.</p><p>Rasanya unik, sedikit pahit segar. Mencerminkan kearifan lokal memanfaatkan hutan.</p>', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=80', 'Palangka Raya', 'https://www.google.com/maps/search/?api=1&query=Juhu%20Singkah%20Kalimantan%20Tengah', 'juhu-singkah'),
  ('kalimantan-tengah', 'Wadi Ikan', '<p>Wadi adalah ikan fermentasi tradisional Dayak yang beraroma kuat dan tahan lama.</p><p>Disantap sebagai lauk dengan nasi. Teknik pengawetan ini diwariskan turun-temurun.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Kalimantan Tengah', 'https://www.google.com/maps/search/?api=1&query=Wadi%20Ikan%20Kalimantan%20Tengah', 'wadi-ikan'),
  ('kalimantan-tengah', 'Pais Sambal', '<p>Pais adalah bumbu dan bahan (ikan/daging) yang dibungkus daun lalu dikukus atau dibakar.</p><p>Versi Kalteng kaya cabai dan rempah hutan. Aromanya sangat menggoda saat dibuka.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Palangka Raya', 'https://www.google.com/maps/search/?api=1&query=Pais%20Sambal%20Kalimantan%20Tengah', 'pais-sambal-kalteng'),
  ('kalimantan-selatan', 'Soto Banjar', '<p>Soto Banjar berkuah bening harum dengan ayam suwir, perkedel, dan telur.</p><p>Rempahnya lembut bergaya Melayu Banjar. Soto Banjar adalah sarapan paling dicari di Kalsel.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Soto_Banjar.jpg/1280px-Soto_Banjar.jpg', 'Banjarmasin', 'https://www.google.com/maps/search/?api=1&query=Soto%20Banjar%20Kalimantan%20Selatan', 'soto-banjar'),
  ('kalimantan-selatan', 'Ketupat Kandangan', '<p>Ketupat Kandangan disajikan dengan ikan haruan (gabus) berkuah santan kuning.</p><p>Kombinasi ketupat dan ikan sungai ini ikon Hulu Sungai Selatan.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Kandangan', 'https://www.google.com/maps/search/?api=1&query=Ketupat%20Kandangan%20Kalimantan%20Selatan', 'ketupat-kandangan'),
  ('kalimantan-selatan', 'Nasi Kuning Banjar', '<p>Nasi Kuning Banjar lebih gurih dengan lauk khas seperti ayam masak habang dan telur.</p><p>Sering menjadi sajian syukuran. Warnanya cerah dari kunyit berkualitas.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Banjarmasin', 'https://www.google.com/maps/search/?api=1&query=Nasi%20Kuning%20Banjar%20Kalimantan%20Selatan', 'nasi-kuning-banjar'),
  ('kalimantan-timur', 'Nasi Bekepor', '<p>Nasi Bekepor adalah nasi liwet khas Kutai yang dimasak dengan rempah dan disajikan dengan lauk ikan atau ayam.</p><p>Dulu makanan bangsawan Kutai, kini dinikmati luas di Samarinda dan sekitarnya.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Samarinda', 'https://www.google.com/maps/search/?api=1&query=Nasi%20Bekepor%20Kalimantan%20Timur', 'nasi-bekepor'),
  ('kalimantan-timur', 'Ayam Cincane', '<p>Ayam Cincane adalah ayam bakar berbumbu merah khas Banjar-Kutai yang manis pedas.</p><p>Warnanya mencolok dan bumbu meresap hingga ke tulang. Favorit di jamuan Kaltim.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Samarinda', 'https://www.google.com/maps/search/?api=1&query=Ayam%20Cincane%20Kalimantan%20Timur', 'ayam-cincane'),
  ('kalimantan-timur', 'Gence Ruan', '<p>Gence Ruan mengolah ikan gabus dengan bumbu pedas merah khas Kutai.</p><p>Daging ikan yang tebal menyerap bumbu sempurna. Lauk berani untuk pecinta pedas.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Tenggarong', 'https://www.google.com/maps/search/?api=1&query=Gence%20Ruan%20Kalimantan%20Timur', 'gence-ruan'),
  ('kalimantan-utara', 'Nasi Lemak Nunukan', '<p>Nasi Lemak Nunukan dipengaruhi kuliner Melayu-Malaysia: nasi santan dengan sambal, ikan, dan telur.</p><p>Posisi perbatasan membuat cita rasanya unik dan berbeda dari nasi lemak Semenanjung.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Nunukan', 'https://www.google.com/maps/search/?api=1&query=Nasi%20Lemak%20Nunukan%20Kalimantan%20Utara', 'nasi-lemak-nunukan'),
  ('kalimantan-utara', 'Kepiting Soka Tarakan', '<p>Kepiting soka Tarakan terkenal karena cangkangnya lunak dan bisa dimakan seluruhnya.</p><p>Biasanya digoreng tepung atau dimasak padang. Jadi andalan wisata kuliner Kaltara.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Tarakan', 'https://www.google.com/maps/search/?api=1&query=Kepiting%20Soka%20Tarakan%20Kalimantan%20Utara', 'kepiting-soka-tarakan'),
  ('kalimantan-utara', 'Ikan Pais Kaltara', '<p>Ikan Pais Kaltara dibungkus daun dengan bumbu cabai lalu dikukus atau dibakar.</p><p>Segar, pedas, dan harum daun. Menonjolkan hasil sungai dan laut Kalimantan Utara.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Tanjung Selor', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Pais%20Kaltara%20Kalimantan%20Utara', 'ikan-pais-kaltara'),
  ('sulawesi-utara', 'Tinutuan', '<p>Tinutuan atau bubur Manado adalah bubur sayur campur dengan labu, kangkung, jagung, dan rempah.</p><p>Disajikan dengan nikah (sambal) dan ikan asin. Sarapan sehat paling Manado.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Tinutuan.jpg/1280px-Tinutuan.jpg', 'Manado', 'https://www.google.com/maps/search/?api=1&query=Tinutuan%20Sulawesi%20Utara', 'tinutuan'),
  ('sulawesi-utara', 'Cakalang Fufu', '<p>Cakalang Fufu adalah ikan cakalang asap khas Bitung yang harum dan tahan lama.</p><p>Bisa dimakan langsung atau diolah jadi sambal goreng. Oleh-oleh laut andalan Sulut.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Bitung', 'https://www.google.com/maps/search/?api=1&query=Cakalang%20Fufu%20Sulawesi%20Utara', 'cakalang-fufu'),
  ('sulawesi-utara', 'Rica-rica Ayam', '<p>Rica-rica membalut ayam dengan cabai merah dan rempah Manado yang sangat pedas.</p><p>Aromanya menusuk dan membuat ketagihan. Wajib dicoba pecinta pedas sejati.</p>', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=1200&q=80', 'Manado', 'https://www.google.com/maps/search/?api=1&query=Rica-rica%20Ayam%20Sulawesi%20Utara', 'rica-rica-ayam-manado'),
  ('sulawesi-tengah', 'Kaledo', '<p>Kaledo adalah kuah tulang kaki sapi dengan kuah asam pedas khas Palu.</p><p>Diminum kuahnya dan dikunyah sumsum tulang. Pengalaman makan yang sangat khas Sulteng.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Palu', 'https://www.google.com/maps/search/?api=1&query=Kaledo%20Sulawesi%20Tengah', 'kaledo'),
  ('sulawesi-tengah', 'Lalampa', '<p>Lalampa adalah ketan isi abon ikan yang dibungkus daun pisang lalu dibakar.</p><p>Camilan khas Palu yang praktis dan gurih. Sering jadi bekal perjalanan.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Palu', 'https://www.google.com/maps/search/?api=1&query=Lalampa%20Sulawesi%20Tengah', 'lalampa'),
  ('sulawesi-tengah', 'Uta Kelo', '<p>Uta Kelo adalah sayur daun kelo (kelor) berkuah santan khas Sulawesi Tengah.</p><p>Sederhana, bergizi, dan sangat rumahan — wajah sehari-hari dapur Palu.</p>', 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?w=1200&q=80', 'Palu', 'https://www.google.com/maps/search/?api=1&query=Uta%20Kelo%20Sulawesi%20Tengah', 'uta-kelo'),
  ('sulawesi-selatan', 'Coto Makassar', '<p>Coto Makassar adalah sup jeroan sapi berkuah kacang tanah dan rempah yang kental gurih.</p><p>Disantap dengan burasa atau ketupat. Ikon kuliner Bugis-Makassar yang mendunia.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Coto_Makassar.jpg/1280px-Coto_Makassar.jpg', 'Makassar', 'https://www.google.com/maps/search/?api=1&query=Coto%20Makassar%20Sulawesi%20Selatan', 'coto-makassar'),
  ('sulawesi-selatan', 'Konro', '<p>Konro adalah iga sapi berkuah hitam manis dari kluwek dan rempah, atau versi bakar.</p><p>Dagingnya empuk hingga lepas tulang. Pasangan sempurna setelah sepiring coto.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Makassar', 'https://www.google.com/maps/search/?api=1&query=Konro%20Sulawesi%20Selatan', 'konro'),
  ('sulawesi-selatan', 'Pallubasa', '<p>Pallubasa mirip coto namun memakai kelapa sangrai yang membuat kuah lebih pekat dan manis gurih.</p><p>Disajikan dengan tauge dan perkedel. Varian yang wajib dicoba di Makassar.</p>', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=1200&q=80', 'Makassar', 'https://www.google.com/maps/search/?api=1&query=Pallubasa%20Sulawesi%20Selatan', 'pallubasa'),
  ('sulawesi-tenggara', 'Sinonggi', '<p>Sinonggi adalah olahan sagu khas Tolaki yang disantap dengan kuah ikan atau sayur.</p><p>Teksturnya kenyal seperti papeda. Makanan pokok yang menggambarkan identitas Sultra.</p>', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1200&q=80', 'Kendari', 'https://www.google.com/maps/search/?api=1&query=Sinonggi%20Sulawesi%20Tenggara', 'sinonggi'),
  ('sulawesi-tenggara', 'Lapa-lapa', '<p>Lapa-lapa adalah ketupat khas yang disajikan dengan kuah santan ikan.</p><p>Sering muncul di hari raya. Gurih santan berpadu ikan segar pesisir Sultra.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Kendari', 'https://www.google.com/maps/search/?api=1&query=Lapa-lapa%20Sulawesi%20Tenggara', 'lapa-lapa-sultra'),
  ('sulawesi-tenggara', 'Kabuto', '<p>Kabuto adalah olahan ubi atau kasbi khas Buton yang dikukus dan disantap dengan lauk ikan.</p><p>Sederhana namun mengenyangkan, mencerminkan pangan lokal kepulauan Buton.</p>', 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=1200&q=80', 'Buton', 'https://www.google.com/maps/search/?api=1&query=Kabuto%20Sulawesi%20Tenggara', 'kabuto'),
  ('gorontalo', 'Binte Biluhuta', '<p>Binte Biluhuta adalah sup jagung dengan udang atau ikan, rasa asam pedas segar.</p><p>Juga disebut milu siram. Hidangan ringan khas Gorontalo yang kaya protein.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Gorontalo', 'https://www.google.com/maps/search/?api=1&query=Binte%20Biluhuta%20Gorontalo', 'binte-biluhuta'),
  ('gorontalo', 'Ilabulo', '<p>Ilabulo terbuat dari adonan sagu dan hati/gizzard ayam berbumbu, dibungkus daun lalu dibakar.</p><p>Teksturnya kenyal gurih. Camilan atau lauk favorit warga Gorontalo.</p>', 'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?w=1200&q=80', 'Gorontalo', 'https://www.google.com/maps/search/?api=1&query=Ilabulo%20Gorontalo', 'ilabulo'),
  ('gorontalo', 'Ayam Iloni', '<p>Ayam Iloni dibumbui rempah lalu dibungkus daun dan dipanggang hingga harum.</p><p>Dagingnya juicy dengan aroma daun. Menu andalan rumah makan Gorontalo.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Gorontalo', 'https://www.google.com/maps/search/?api=1&query=Ayam%20Iloni%20Gorontalo', 'ayam-iloni'),
  ('sulawesi-barat', 'Jepa', '<p>Jepa adalah roti pipih dari tepung singkong khas Mandar yang dipanggang di atas wajan.</p><p>Disantap dengan ikan atau sambal. Makanan pokok alternatif yang sangat Mandar.</p>', 'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=1200&q=80', 'Mamuju', 'https://www.google.com/maps/search/?api=1&query=Jepa%20Sulawesi%20Barat', 'jepa'),
  ('sulawesi-barat', 'Bau Peapi', '<p>Bau Peapi adalah ikan berkuah kuning berempah khas Mandar dengan rasa pedas gurih.</p><p>Nama secara harfiah terkait ''bau'' (masak) ikan. Lauk sehari-hari yang kaya rasa.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Polewali Mandar', 'https://www.google.com/maps/search/?api=1&query=Bau%20Peapi%20Sulawesi%20Barat', 'bau-peapi'),
  ('sulawesi-barat', 'Lapa-lapa Mandar', '<p>Lapa-lapa Mandar adalah ketupat santan yang disajikan pada hari besar Islam di Mandar.</p><p>Teksturnya pulen gurih. Simbol perayaan dan silaturahmi keluarga.</p>', 'https://images.unsplash.com/photo-1516684669134-de6f7c473a2a?w=1200&q=80', 'Majene', 'https://www.google.com/maps/search/?api=1&query=Lapa-lapa%20Mandar%20Sulawesi%20Barat', 'lapa-lapa-mandar'),
  ('maluku', 'Papeda Maluku', '<p>Papeda adalah bubur sagu kenyal yang disantap dengan ikan kuah kuning khas Maluku.</p><p>Makanan pokok Timur Indonesia. Cara makannya dengan menggulung memakai sumpit atau garpu khas.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg/1280px-Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg', 'Ambon', 'https://www.google.com/maps/search/?api=1&query=Papeda%20Maluku%20Maluku', 'papeda-maluku'),
  ('maluku', 'Ikan Kuah Kuning Ambon', '<p>Ikan Kuah Kuning memakai kunyit, kemiri, dan asam untuk kuah segar yang menemani papeda.</p><p>Ikan tongkol atau kakap sering dipakai. Segar, pedas, dan sangat Ambon.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Ambon', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Kuah%20Kuning%20Ambon%20Maluku', 'ikan-kuah-kuning-ambon'),
  ('maluku', 'Kohu-kohu', '<p>Kohu-kohu adalah salad kelapa, sayuran, dan ikan asap atau tongkol dengan bumbu jeruk.</p><p>Rasanya segar asam pedas. Cocok sebagai pelengkap papeda atau nasi.</p>', 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?w=1200&q=80', 'Ambon', 'https://www.google.com/maps/search/?api=1&query=Kohu-kohu%20Maluku', 'kohu-kohu'),
  ('maluku-utara', 'Gohu Ikan', '<p>Gohu Ikan adalah ''sashimi'' Ternate: ikan mentah segar dibumbui jeruk, cabai, dan bawang.</p><p>Kesegarannya bergantung pada kualitas ikan. Kebanggaan kuliner Maluku Utara.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Ternate', 'https://www.google.com/maps/search/?api=1&query=Gohu%20Ikan%20Maluku%20Utara', 'gohu-ikan'),
  ('maluku-utara', 'Ikan Bakar Rica Ternate', '<p>Ikan bakar dengan bumbu rica khas Ternate yang pedas dan harum.</p><p>Disajikan dengan sambal dan papeda atau nasi. Hidangan pantai yang mewakili Malut.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Ternate', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Bakar%20Rica%20Ternate%20Maluku%20Utara', 'ikan-bakar-rica-ternate'),
  ('maluku-utara', 'Sagu Lempeng Malut', '<p>Sagu Lempeng adalah kerupuk/pipih sagu yang digoreng atau dipanggang sebagai camilan atau pengganti nasi.</p><p>Ringan dan renyah. Bagian penting pangan tradisional kepulauan Maluku Utara.</p>', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1200&q=80', 'Halmahera', 'https://www.google.com/maps/search/?api=1&query=Sagu%20Lempeng%20Malut%20Maluku%20Utara', 'sagu-lempeng-malut'),
  ('papua', 'Papeda Papua', '<p>Papeda Papua adalah bubur sagu yang menjadi makanan pokok banyak komunitas di Papua.</p><p>Biasanya disandingkan dengan ikan kuah kuning atau sayur bayam. Simbol kuliner Tanah Papua.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg/1280px-Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg', 'Jayapura', 'https://www.google.com/maps/search/?api=1&query=Papeda%20Papua%20Papua', 'papeda-papua'),
  ('papua', 'Ikan Bakar Batu', '<p>Ikan Bakar Batu merujuk tradisi memasak dengan batu panas di dalam lubang tanah (bakar batu).</p><p>Teknik komunal ini dipakai saat perayaan. Rasa asap dan rempahnya sangat khas.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Jayapura', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Bakar%20Batu%20Papua', 'ikan-bakar-batu'),
  ('papua', 'Keladi Tumbuk', '<p>Keladi Tumbuk mengolah umbi keladi yang ditumbuk dan disajikan sebagai sumber karbohidrat lokal.</p><p>Teksturnya lembut. Bagian dari diversifikasi pangan tradisional Papua.</p>', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=80', 'Papua', 'https://www.google.com/maps/search/?api=1&query=Keladi%20Tumbuk%20Papua', 'keladi-tumbuk'),
  ('papua-barat', 'Ikan Bakar Manokwari', '<p>Ikan Bakar Manokwari dilumuri bumbu merica dan cabai lalu dibakar hingga harum.</p><p>Kesegaran ikan Teluk Cenderawasih jadi kuncinya. Favorit warga dan pendatang.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Manokwari', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Bakar%20Manokwari%20Papua%20Barat', 'ikan-bakar-manokwari'),
  ('papua-barat', 'Udang Selingkuh', '<p>Udang Selingkuh adalah julukan lokal untuk lobster air tawar Sungai Aimasi yang manis dagingnya.</p><p>Biasanya direbus atau dibakar sederhana. Ikon kuliner unik Papua Barat.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Manokwari', 'https://www.google.com/maps/search/?api=1&query=Udang%20Selingkuh%20Papua%20Barat', 'udang-selingkuh'),
  ('papua-barat', 'Papeda Papua Barat', '<p>Papeda di Papua Barat disajikan sama seperti di kawasan Timur lain: dengan ikan kuah kuning.</p><p>Kental, kenyal, dan mengenyangkan. Tetap jadi tulang punggung pangan lokal.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg/1280px-Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg', 'Manokwari', 'https://www.google.com/maps/search/?api=1&query=Papeda%20Papua%20Barat%20Papua%20Barat', 'papeda-papua-barat'),
  ('papua-selatan', 'Ikan Bakar Merauke', '<p>Ikan Bakar Merauke memanfaatkan hasil perairan selatan Papua dengan bumbu sederhana pedas gurih.</p><p>Daging ikannya tebal dan manis. Sering jadi menu utama di meja keluarga Merauke.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Merauke', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Bakar%20Merauke%20Papua%20Selatan', 'ikan-bakar-merauke'),
  ('papua-selatan', 'Sagu Bakar Merauke', '<p>Sagu Bakar diolah dari sagu basah yang dipanggang hingga berwarna kecokelatan.</p><p>Camilan atau pengganti nasi dengan rasa netral yang cocok dengan ikan kuah.</p>', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1200&q=80', 'Merauke', 'https://www.google.com/maps/search/?api=1&query=Sagu%20Bakar%20Merauke%20Papua%20Selatan', 'sagu-bakar-merauke'),
  ('papua-selatan', 'Kue Sagu Seluk', '<p>Kue Sagu Seluk adalah kudapan sagu dengan kelapa atau gula merah khas Papua Selatan.</p><p>Teksturnya kenyal manis. Sering muncul di pasar tradisional Merauke.</p>', 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=1200&q=80', 'Merauke', 'https://www.google.com/maps/search/?api=1&query=Kue%20Sagu%20Seluk%20Papua%20Selatan', 'kue-sagu-seluk'),
  ('papua-tengah', 'Ubi Bakar Paniai', '<p>Ubi Bakar Paniai menonjolkan ubi jalar pegunungan yang manis alami setelah dibakar.</p><p>Sumber energi utama masyarakat dataran tinggi Papua Tengah.</p>', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=80', 'Paniai', 'https://www.google.com/maps/search/?api=1&query=Ubi%20Bakar%20Paniai%20Papua%20Tengah', 'ubi-bakar-paniai'),
  ('papua-tengah', 'Ikan Semur Timika', '<p>Ikan Semur Timika mengolah ikan lokal dengan bumbu kecap dan rempah yang manis gurih.</p><p>Pengaruh kuliner urban Timika berpadu bahan lokal. Cocok dengan nasi putih.</p>', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?w=1200&q=80', 'Mimika', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Semur%20Timika%20Papua%20Tengah', 'ikan-semur-timika'),
  ('papua-tengah', 'Papeda Nabire', '<p>Papeda Nabire disajikan dengan ikan kuah dari hasil tangkapan Teluk Cenderawasih bagian selatan.</p><p>Tetap kenyal dan mengenyangkan, dengan kuah yang lebih ringan.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg/1280px-Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg', 'Nabire', 'https://www.google.com/maps/search/?api=1&query=Papeda%20Nabire%20Papua%20Tengah', 'papeda-nabire'),
  ('papua-pegunungan', 'Hipere', '<p>Hipere adalah ubi jalar manis khas pegunungan yang menjadi pangan pokok di Wamena dan sekitarnya.</p><p>Dikukus atau dibakar. Warna dan manisnya berbeda dari ubi dataran rendah.</p>', 'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=1200&q=80', 'Wamena', 'https://www.google.com/maps/search/?api=1&query=Hipere%20Papua%20Pegunungan', 'hipere'),
  ('papua-pegunungan', 'Babi Bakar Wamena', '<p>Babi Bakar Wamena dimasak dalam upacara bakar batu bersama ubi dan sayur lokal.</p><p>Dagingnya empuk berasap. Bagian penting budaya dan kuliner pegunungan Papua.</p>', 'https://images.unsplash.com/photo-1529042410759-befb1204b468?w=1200&q=80', 'Wamena', 'https://www.google.com/maps/search/?api=1&query=Babi%20Bakar%20Wamena%20Papua%20Pegunungan', 'babi-bakar-wamena'),
  ('papua-pegunungan', 'Ubi Jalar Honai', '<p>Ubi Jalar Honai merujuk sajian ubi di sekitar rumah adat honai, dimasak sederhana di tungku.</p><p>Rasa manis natural dan tekstur lembut menjadikannya makanan sehari-hari paling berharga.</p>', 'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?w=1200&q=80', 'Jayawijaya', 'https://www.google.com/maps/search/?api=1&query=Ubi%20Jalar%20Honai%20Papua%20Pegunungan', 'ubi-jalar-honai'),
  ('papua-barat-daya', 'Ikan Kuah Kuning Sorong', '<p>Ikan Kuah Kuning Sorong memakai ikan laut segar Raja Ampat–Sorong dengan kuah kunyit asam.</p><p>Segar dan pedas ringan. Pasangan ideal untuk papeda atau nasi.</p>', 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=1200&q=80', 'Sorong', 'https://www.google.com/maps/search/?api=1&query=Ikan%20Kuah%20Kuning%20Sorong%20Papua%20Barat%20Daya', 'ikan-kuah-kuning-sorong'),
  ('papua-barat-daya', 'Papeda Sorong', '<p>Papeda Sorong sama kenyalnya dengan papeda kawasan Timur lain, disajikan di banyak rumah makan lokal.</p><p>Menjadi pengantar wisatawan menuju kuliner kepulauan Raja Ampat.</p>', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg/1280px-Papeda%2C_Ikan_Kuah_Kuning%2C_Ikan_Bakar%2C_Sambal.jpg', 'Sorong', 'https://www.google.com/maps/search/?api=1&query=Papeda%20Sorong%20Papua%20Barat%20Daya', 'papeda-sorong'),
  ('papua-barat-daya', 'Sambal Colo-colo Sorong', '<p>Sambal Colo-colo adalah sambal segar dari cabai, tomat, bawang, dan jeruk nipis khas Timur.</p><p>Pelengkap ikan bakar yang wajib. Versi Sorong cenderung sangat segar dan pedas.</p>', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=1200&q=80', 'Sorong', 'https://www.google.com/maps/search/?api=1&query=Sambal%20Colo-colo%20Sorong%20Papua%20Barat%20Daya', 'sambal-colo-colo-sorong')
) AS v(province_slug, name, content, media_url, location, maps_url, slug)
JOIN provinces p ON p.slug = v.province_slug;

COMMIT;
